// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != c.owner());
        vm.assume(newOwner != c.owner());
        address originalOwner = c.owner();
        vm.prank(caller);
        try c.setOwner(newOwner) { } catch { }
        bool callerIsAdmin = (caller == address(this));
        if (callerIsAdmin) {
            assertTrue(c.owner() == newOwner || c.owner() == originalOwner);
        } else {
            assertTrue(c.owner() == originalOwner);
        }
    }
}
